package com.samanramezani1377.woogit.data.network

import com.samanramezani1377.woogit.core.security.CredentialPair

/** Compatibility facade: every Customer API operation is transported through WooGit Backend /forward. */
class WooCommerceApi(private val backend: BackendClient, private val storeId: String, private val credentials: CredentialPair) {
    suspend fun validateStore()=get("/wp-json/wc/v3/system_status")
    suspend fun listOrders(page:Int=1,perPage:Int=20,search:String?=null,status:String?=null)=get("/wp-json/wc/v3/orders",q(page,perPage,search,status))
    suspend fun getOrder(id:Long)=get("/wp-json/wc/v3/orders/$id")
    suspend fun updateOrder(id:Long,body:String,idempotencyKey:String?=null)=mut("/wp-json/wc/v3/orders/$id","PUT",body,idempotencyKey=idempotencyKey)
    suspend fun listOrderNotes(id:Long,page:Int=1,perPage:Int=100)=get("/wp-json/wc/v3/orders/$id/notes",q(page,perPage))
    suspend fun addOrderNote(id:Long,body:String,idempotencyKey:String?=null)=mut("/wp-json/wc/v3/orders/$id/notes","POST",body,idempotencyKey=idempotencyKey)
    suspend fun deleteOrder(id:Long,force:Boolean=false,idempotencyKey:String?=null)=mut("/wp-json/wc/v3/orders/$id","DELETE",null,mapOf("force" to force),idempotencyKey=idempotencyKey)
    suspend fun salesReport(dateMin:String,dateMax:String)=get("/wp-json/wc/v3/reports/sales",mapOf("date_min" to dateMin,"date_max" to dateMax))
    suspend fun listProducts(page:Int=1,perPage:Int=20,search:String?=null,modifiedAfter:String?=null)=get("/wp-json/wc/v3/products",q(page,perPage,search,null,modifiedAfter))
    suspend fun getProduct(id:Long)=get("/wp-json/wc/v3/products/$id")
    suspend fun createProduct(body:String,idempotencyKey:String?=null)=mut("/wp-json/wc/v3/products","POST",body,idempotencyKey=idempotencyKey)
    suspend fun updateProduct(id:Long,body:String,idempotencyKey:String?=null)=mut("/wp-json/wc/v3/products/$id","PUT",body,idempotencyKey=idempotencyKey)
    suspend fun deleteProduct(id:Long,force:Boolean=false,idempotencyKey:String?=null)=mut("/wp-json/wc/v3/products/$id","DELETE",null,mapOf("force" to force),idempotencyKey=idempotencyKey)
    suspend fun listProductCategories(page:Int=1,perPage:Int=100,search:String?=null)=get("/wp-json/wc/v3/products/categories",q(page,perPage,search))
    suspend fun createProductCategory(body:String,idempotencyKey:String?=null)=mut("/wp-json/wc/v3/products/categories","POST",body,idempotencyKey=idempotencyKey)
    suspend fun listVariations(productId:Long,page:Int=1,perPage:Int=20)=get("/wp-json/wc/v3/products/$productId/variations",q(page,perPage))
    suspend fun getVariation(productId:Long,id:Long)=get("/wp-json/wc/v3/products/$productId/variations/$id")
    suspend fun createVariation(productId:Long,body:String,idempotencyKey:String?=null)=mut("/wp-json/wc/v3/products/$productId/variations","POST",body,idempotencyKey=idempotencyKey)
    suspend fun updateVariation(productId:Long,id:Long,body:String,idempotencyKey:String?=null)=mut("/wp-json/wc/v3/products/$productId/variations/$id","PUT",body,idempotencyKey=idempotencyKey)
    suspend fun deleteVariation(productId:Long,id:Long,force:Boolean=false,idempotencyKey:String?=null)=mut("/wp-json/wc/v3/products/$productId/variations/$id","DELETE",null,mapOf("force" to force),idempotencyKey=idempotencyKey)
    suspend fun listAttributes(page:Int=1,perPage:Int=100)=get("/wp-json/wc/v3/products/attributes",q(page,perPage))
    suspend fun getAttribute(id:Long)=get("/wp-json/wc/v3/products/attributes/$id")
    suspend fun createAttribute(body:String,idempotencyKey:String?=null)=mut("/wp-json/wc/v3/products/attributes","POST",body,idempotencyKey=idempotencyKey)
    suspend fun updateAttribute(id:Long,body:String,idempotencyKey:String?=null)=mut("/wp-json/wc/v3/products/attributes/$id","PUT",body,idempotencyKey=idempotencyKey)
    suspend fun deleteAttribute(id:Long,force:Boolean=false,idempotencyKey:String?=null)=mut("/wp-json/wc/v3/products/attributes/$id","DELETE",null,mapOf("force" to force),idempotencyKey=idempotencyKey)
    suspend fun listAttributeTerms(attributeId:Long,page:Int=1,perPage:Int=100)=get("/wp-json/wc/v3/products/attributes/$attributeId/terms",q(page,perPage))
    suspend fun getAttributeTerm(attributeId:Long,id:Long)=get("/wp-json/wc/v3/products/attributes/$attributeId/terms/$id")
    suspend fun createAttributeTerm(attributeId:Long,body:String,idempotencyKey:String?=null)=mut("/wp-json/wc/v3/products/attributes/$attributeId/terms","POST",body,idempotencyKey=idempotencyKey)
    suspend fun updateAttributeTerm(attributeId:Long,id:Long,body:String,idempotencyKey:String?=null)=mut("/wp-json/wc/v3/products/attributes/$attributeId/terms/$id","PUT",body,idempotencyKey=idempotencyKey)
    suspend fun deleteAttributeTerm(attributeId:Long,id:Long,force:Boolean=false,idempotencyKey:String?=null)=mut("/wp-json/wc/v3/products/attributes/$attributeId/terms/$id","DELETE",null,mapOf("force" to force),idempotencyKey=idempotencyKey)
    suspend fun listMedia(page:Int=1,perPage:Int=30,search:String?=null)=get("/wp-json/wp/v2/media",q(page,perPage,search))
    suspend fun uploadMedia(fileName:String,bytes:ByteArray,mediaType:String,idempotencyKey:String?=null)=backend.forwardBinary(storeId,"/wp-json/wp/v2/media","POST",credentials,emptyMap(),bytes,mediaType,fileName,idempotencyKey)
    suspend fun deleteMedia(mediaId:Long,force:Boolean=true,idempotencyKey:String?=null)=mut("/wp-json/wp/v2/media/$mediaId","DELETE",null,mapOf("force" to force),idempotencyKey=idempotencyKey)
    suspend fun downloadMedia(sourceUrl:String):ByteArray=error("Direct image download is owned by ImageFetcher, not WooCommerceApi")

    @Deprecated("Routing is owned by Backend; baseUrl is ignored. Use validateStore().")
    suspend fun validateStore(baseUrl:String)=validateStore()
    @Deprecated("Routing is owned by Backend; baseUrl is ignored. Use listOrders(page, perPage, search, status).")
    suspend fun listOrders(b:String,page:Int=1,perPage:Int=20,search:String?=null,status:String?=null)=listOrders(page,perPage,search,status)
    @Deprecated("Routing is owned by Backend; baseUrl is ignored. Use getOrder(id).")
    suspend fun getOrder(b:String,id:Long)=getOrder(id)
    @Deprecated("Routing is owned by Backend; baseUrl is ignored. Use updateOrder(id, body, idempotencyKey).")
    suspend fun updateOrder(b:String,id:Long,body:String,idempotencyKey:String?=null)=updateOrder(id,body,idempotencyKey)
    @Deprecated("Routing is owned by Backend; baseUrl is ignored. Use listOrderNotes(id, page, perPage).")
    suspend fun listOrderNotes(b:String,id:Long,page:Int=1,perPage:Int=100)=listOrderNotes(id,page,perPage)
    @Deprecated("Routing is owned by Backend; baseUrl is ignored. Use addOrderNote(id, body, idempotencyKey).")
    suspend fun addOrderNote(b:String,id:Long,body:String,idempotencyKey:String?=null)=addOrderNote(id,body,idempotencyKey)
    @Deprecated("Routing is owned by Backend; baseUrl is ignored. Use deleteOrder(id, force, idempotencyKey).")
    suspend fun deleteOrder(b:String,id:Long,force:Boolean=false,idempotencyKey:String?=null)=deleteOrder(id,force,idempotencyKey)
    @Deprecated("Routing is owned by Backend; baseUrl is ignored. Use salesReport(dateMin, dateMax).")
    suspend fun salesReport(b:String,dateMin:String,dateMax:String)=salesReport(dateMin,dateMax)
    @Deprecated("Routing is owned by Backend; baseUrl is ignored. Use listProducts(page, perPage, search, modifiedAfter).")
    suspend fun listProducts(b:String,page:Int=1,perPage:Int=20,search:String?=null,modifiedAfter:String?=null)=listProducts(page,perPage,search,modifiedAfter)
    @Deprecated("Routing is owned by Backend; baseUrl is ignored. Use getProduct(id).")
    suspend fun getProduct(b:String,id:Long)=getProduct(id)
    @Deprecated("Routing is owned by Backend; baseUrl is ignored. Use createProduct(body, idempotencyKey).")
    suspend fun createProduct(b:String,body:String,idempotencyKey:String?=null)=createProduct(body,idempotencyKey)
    @Deprecated("Routing is owned by Backend; baseUrl is ignored. Use updateProduct(id, body, idempotencyKey).")
    suspend fun updateProduct(b:String,id:Long,body:String,idempotencyKey:String?=null)=updateProduct(id,body,idempotencyKey)
    @Deprecated("Routing is owned by Backend; baseUrl is ignored. Use deleteProduct(id, force, idempotencyKey).")
    suspend fun deleteProduct(b:String,id:Long,force:Boolean=false,idempotencyKey:String?=null)=deleteProduct(id,force,idempotencyKey)
    @Deprecated("Routing is owned by Backend; baseUrl is ignored. Use listProductCategories(page, perPage, search).")
    suspend fun listProductCategories(b:String,page:Int=1,perPage:Int=100,search:String?=null)=listProductCategories(page,perPage,search)
    @Deprecated("Routing is owned by Backend; baseUrl is ignored. Use createProductCategory(body, idempotencyKey).")
    suspend fun createProductCategory(b:String,body:String,idempotencyKey:String?=null)=createProductCategory(body,idempotencyKey)
    @Deprecated("Routing is owned by Backend; baseUrl is ignored. Use listVariations(productId, page, perPage).")
    suspend fun listVariations(b:String,productId:Long,page:Int=1,perPage:Int=20)=listVariations(productId,page,perPage)
    @Deprecated("Routing is owned by Backend; baseUrl is ignored. Use getVariation(productId, id).")
    suspend fun getVariation(b:String,productId:Long,id:Long)=getVariation(productId,id)
    @Deprecated("Routing is owned by Backend; baseUrl is ignored. Use createVariation(productId, body, idempotencyKey).")
    suspend fun createVariation(b:String,productId:Long,body:String,idempotencyKey:String?=null)=createVariation(productId,body,idempotencyKey)
    @Deprecated("Routing is owned by Backend; baseUrl is ignored. Use updateVariation(productId, id, body, idempotencyKey).")
    suspend fun updateVariation(b:String,productId:Long,id:Long,body:String,idempotencyKey:String?=null)=updateVariation(productId,id,body,idempotencyKey)
    @Deprecated("Routing is owned by Backend; baseUrl is ignored. Use deleteVariation(productId, id, force, idempotencyKey).")
    suspend fun deleteVariation(b:String,productId:Long,id:Long,force:Boolean=false,idempotencyKey:String?=null)=deleteVariation(productId,id,force,idempotencyKey)
    @Deprecated("Routing is owned by Backend; baseUrl is ignored. Use listAttributes(page, perPage).")
    suspend fun listAttributes(b:String,page:Int=1,perPage:Int=100)=listAttributes(page,perPage)
    @Deprecated("Routing is owned by Backend; baseUrl is ignored. Use getAttribute(id).")
    suspend fun getAttribute(b:String,id:Long)=getAttribute(id)
    @Deprecated("Routing is owned by Backend; baseUrl is ignored. Use createAttribute(body, idempotencyKey).")
    suspend fun createAttribute(b:String,body:String,idempotencyKey:String?=null)=createAttribute(body,idempotencyKey)
    @Deprecated("Routing is owned by Backend; baseUrl is ignored. Use updateAttribute(id, body, idempotencyKey).")
    suspend fun updateAttribute(b:String,id:Long,body:String,idempotencyKey:String?=null)=updateAttribute(id,body,idempotencyKey)
    @Deprecated("Routing is owned by Backend; baseUrl is ignored. Use deleteAttribute(id, force, idempotencyKey).")
    suspend fun deleteAttribute(b:String,id:Long,force:Boolean=false,idempotencyKey:String?=null)=deleteAttribute(id,force,idempotencyKey)
    @Deprecated("Routing is owned by Backend; baseUrl is ignored. Use listAttributeTerms(attributeId, page, perPage).")
    suspend fun listAttributeTerms(b:String,attributeId:Long,page:Int=1,perPage:Int=100)=listAttributeTerms(attributeId,page,perPage)
    @Deprecated("Routing is owned by Backend; baseUrl is ignored. Use getAttributeTerm(attributeId, id).")
    suspend fun getAttributeTerm(b:String,attributeId:Long,id:Long)=getAttributeTerm(attributeId,id)
    @Deprecated("Routing is owned by Backend; baseUrl is ignored. Use createAttributeTerm(attributeId, body, idempotencyKey).")
    suspend fun createAttributeTerm(b:String,attributeId:Long,body:String,idempotencyKey:String?=null)=createAttributeTerm(attributeId,body,idempotencyKey)
    @Deprecated("Routing is owned by Backend; baseUrl is ignored. Use updateAttributeTerm(attributeId, id, body, idempotencyKey).")
    suspend fun updateAttributeTerm(b:String,attributeId:Long,id:Long,body:String,idempotencyKey:String?=null)=updateAttributeTerm(attributeId,id,body,idempotencyKey)
    @Deprecated("Routing is owned by Backend; baseUrl is ignored. Use deleteAttributeTerm(attributeId, id, force, idempotencyKey).")
    suspend fun deleteAttributeTerm(b:String,attributeId:Long,id:Long,force:Boolean=false,idempotencyKey:String?=null)=deleteAttributeTerm(attributeId,id,force,idempotencyKey)
    @Deprecated("Routing is owned by Backend; baseUrl is ignored. Use listMedia(page, perPage, search).")
    suspend fun listMedia(b:String,page:Int=1,perPage:Int=30,search:String?=null)=listMedia(page,perPage,search)
    @Deprecated("Routing is owned by Backend; baseUrl is ignored. Use uploadMedia(fileName, bytes, mediaType, idempotencyKey).")
    suspend fun uploadMedia(b:String,fileName:String,bytes:ByteArray,mediaType:String,idempotencyKey:String?=null)=uploadMedia(fileName,bytes,mediaType,idempotencyKey)
    @Deprecated("Routing is owned by Backend; baseUrl is ignored. Use deleteMedia(mediaId, force, idempotencyKey).")
    suspend fun deleteMedia(b:String,mediaId:Long,force:Boolean=true,idempotencyKey:String?=null)=deleteMedia(mediaId,force,idempotencyKey)
    @Deprecated("Routing is owned by Backend; baseUrl is ignored. Use downloadMedia(sourceUrl).")
    suspend fun downloadMedia(b:String,sourceUrl:String):ByteArray=downloadMedia(sourceUrl)

    private suspend fun get(path:String,query:Map<String,Any> = emptyMap())=backend.forward(storeId,path,"GET",credentials,query)
    private suspend fun mut(path:String,method:String,body:String?,query:Map<String,Any> = emptyMap(),idempotencyKey:String?=null)=backend.forward(storeId,path,method,credentials,query,body,idempotencyKey)
    private fun q(page:Int,perPage:Int,search:String?=null,status:String?=null,modifiedAfter:String?=null)=buildMap<String,Any>{put("page",page);put("per_page",perPage);if(!search.isNullOrBlank())put("search",search);if(!status.isNullOrBlank())put("status",status);if(!modifiedAfter.isNullOrBlank()){put("modified_after",modifiedAfter);put("dates_are_gmt",true)}}
}

data class ApiResponse(val statusCode:Int,val body:String,val method:String="",val endpoint:String="",val headers:Map<String,String> = emptyMap()){val total:Int? get()=headers["x-wp-total"]?.toIntOrNull();val totalPages:Int? get()=headers["x-wp-totalpages"]?.toIntOrNull()}
